    left join golden_fund_fund_committed_capital_usd
        on golden_fund_fund_committed_capital_usd.fund_hk = golden_fund_hub.fund_hk
    left join golden_fund_fund_status
        on golden_fund_fund_status.fund_hk = golden_fund_hub.fund_hk
    left join golden_fund_fund_external_identity
        on golden_fund_fund_external_identity.fund_hk = golden_fund_hub.fund_hk
    left join golden_fund_fund_lei
